def toposort(deps):
    # Build full set of nodes
    all_nodes = set(deps.keys())
    for lst in deps.values():
        all_nodes.update(lst)

    # Map node -> list of dependents (reverse edges)
    dependents = {node: [] for node in all_nodes}
    for node, prereqs in deps.items():
        for p in prereqs:
            # If a prerequisite is not in deps keys, it's still a node
            dependents[p].append(node)

    # In-degree map
    indeg = {node: 0 for node in all_nodes}
    for node, prereqs in deps.items():
        for p in prereqs:
            indeg[node] += 1

    # Nodes with zero indegree
    zero_nodes = sorted([node for node in all_nodes if indeg[node] == 0])

    result = []
    while zero_nodes:
        # pick alphabetically smallest
        cur = zero_nodes[0]
        zero_nodes.pop(0)
        result.append(cur)

        for nxt in dependents[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                zero_nodes.append(nxt)
        # keep zero_nodes sorted for deterministic choice
        zero_nodes.sort()

    if len(result) != len(all_nodes):
        # cycle detected
        raise ValueError("cycle")

    return result
