class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._cache = {}                     # key -> (value, order)
        self._order = []                     # list of keys in LRU order (oldest first)
        self._next_order_id = 0              # unique increasing id for insertion order

    def get(self, key):
        if key not in self._cache:
            return None
        # mark as most recently used: remove from current order and append at end
        self._order.remove(key)
        self._order.append(key)
        # keep value and order id unchanged
        return self._cache[key][0]

    def put(self, key, value):
        if key in self._cache:
            # update existing: remove old occurrence from order
            self._order.remove(key)
        else:
            # new key: assign new order id
            self._next_order_id += 1
        self._cache[key] = (value, self._next_order_id)
        self._order.append(key)

        # if over capacity, drop least recently used (first element of _order)
        if len(self._order) > self.capacity:
            lru_key = self._order.pop(0)
            del self._cache[lru_key]

    def __len__(self):
        return len(self._cache)

    def keys(self):
        # return keys from least recently used to most recently used
        # _order already stores keys in that order (oldest first)
        return self._order[:]
