class Inventory:
    def __init__(self, stock=None):
        # copy the provided stock dict to avoid mutating the original
        self._stock = dict(stock) if stock is not None else {}

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty < 0:
            raise ValueError("quantity must be non-negative")
        # qty == 0 is allowed (adds nothing)
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty < 0:
            raise ValueError("quantity must be non-negative")
        if qty == 0:
            return  # nothing to remove
        current = self.stock(item)
        if qty > current:
            raise OutOfStock(f"Not enough stock for {item}: need {qty}, have {current}")
        self._stock[item] = current - qty


def fulfil(inventory, order):
    if not isinstance(order, dict):
        raise TypeError("order must be a dict")
    # Validate order quantities first
    for item, qty in order.items():
        if qty < 0:
            raise ValueError(f"Negative quantity {qty} for item {item} in order")
        # qty == 0 is allowed (nothing to fulfil)
    # Work on a temporary copy so that on OutOfStock we can restore the original state
    temp_inv = Inventory(inventory._stock)  # copy constructor uses dict copy
    total = 0
    for item, qty in order.items():
        try:
            temp_inv.remove(item, qty)
            total += qty
        except OutOfStock:
            # restore original inventory and return 0
            return 0
